mapper.select:
select tsse.*,tsp.name
from tb_screen_sputum_examination tsse
left join tb_screen_person tsp on tsse.person_id=tsp.id
where tsp.screen_point=#{screenPoint}
and tsse.year=#{year}
and tsse.deleted=0
and tsp.deleted=0

    and tsse.screen_id like concat('%',#{screenId},'%')


    and tsse.atomization=#{atomization}

order by tsse.id desc

    limit #{pageNo},#{pageSize}

select ifnull(count(*),0)
from tb_screen_sputum_examination tsse
left join tb_screen_person tsp on tsse.person_id=tsp.id
where tsp.screen_point=#{screenPoint}
and tsse.year=#{year}
and tsse.deleted=0
and tsp.deleted=0

    and tsse.screen_id like concat('%',#{screenId},'%')


    and tsse.atomization=#{atomization}

select screen_order
from tb_screen_sputum_examination
where id=#{id}
